import{_ as e,o as a,c as d,ag as o}from"./chunks/framework.C5oN-8Wt.js";const m=JSON.parse('{"title":"复数乘法器","description":"","frontmatter":{},"headers":[],"relativePath":"v0.1.0-alpha/modules/complex_multiply/index.md","filePath":"v0.1.0-alpha/modules/complex_multiply/index.md"}'),r={name:"v0.1.0-alpha/modules/complex_multiply/index.md"};function l(i,t,h,n,c,p){return a(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="复数乘法器" tabindex="-1">复数乘法器 <a class="header-anchor" href="#复数乘法器" aria-label="Permalink to &quot;复数乘法器&quot;">​</a></h1><p>适用：v0.1.0-alpha · GNU Radio 3.10.12.0<br> 模块类型：<code>complex_multiply</code> · 模块定义版本：5</p><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>逐位置相乘复数样本。若把两个复数写成幅度与相位，乘积的幅度相乘、相位相加，因此可用于复数混频和相位调制实验。</p><h2 id="典型接线" tabindex="-1">典型接线 <a class="header-anchor" href="#典型接线" aria-label="Permalink to &quot;典型接线&quot;">​</a></h2><p><code>复数信号源 1.out → 复数乘法器.in1</code>，<code>复数信号源 2.out → 复数乘法器.in2</code>。将乘积绑定到观察器，比较输入与输出的旋转速度和频谱位置。</p><p>下表为内置默认参数下的端口。带路数、元素类型或 vlen 的模块会随参数改变流端口。</p><table tabindex="0"><thead><tr><th>方向</th><th>端口</th><th>数据类型</th><th>单位 / 形状</th></tr></thead><tbody><tr><td>输入</td><td><code>in1</code>（输入 1）</td><td><code>complex_f64</code></td><td>归一化幅度；vlen=1</td></tr><tr><td>输入</td><td><code>in2</code>（输入 2）</td><td><code>complex_f64</code></td><td>归一化幅度；vlen=1</td></tr><tr><td>输出</td><td><code>out</code>（输出）</td><td><code>complex_f64</code></td><td>归一化幅度；vlen=1</td></tr></tbody></table><h2 id="参数怎么用" tabindex="-1">参数怎么用 <a class="header-anchor" href="#参数怎么用" aria-label="Permalink to &quot;参数怎么用&quot;">​</a></h2><p>各输入应具有相同向量长度与 item 速率。这里执行普通复数乘法，不会自动对某一路取共轭；两个正频率相量相乘时频率相加，求差频需明确构造相反旋转的输入。</p><p>混频后频率仍要落在采样率允许的范围内，否则会混叠。增大图表横轴不能恢复已经折叠的频率。</p><p>内置默认值如下；本机设置可为<strong>新实例</strong>指定其他默认值，打开已有工程保留工程参数。</p><table tabindex="0"><thead><tr><th>参数</th><th>内置默认值</th><th>取值与约束</th><th>修改时机</th></tr></thead><tbody><tr><td>输入路数<br><code>num_inputs</code></td><td><code>2</code></td><td>范围 1 至 1024；当前画布支持 1–1024 路。修改后须重新准备，缩减前请先解除相关连线和工具绑定。</td><td>重新准备</td></tr><tr><td>每个 item 的向量长度<br><code>vlen</code></td><td><code>1</code></td><td>范围 1 至 1024；Master 当前容量限制为 1–1024；采样率按 item 计。</td><td>重新准备</td></tr></tbody></table><h2 id="在线修改与重新准备" tabindex="-1">在线修改与重新准备 <a class="header-anchor" href="#在线修改与重新准备" aria-label="Permalink to &quot;在线修改与重新准备&quot;">​</a></h2><p>计算参数或结构变化后，先停止，再重新准备和运行。</p><p>改变输入路数或向量长度需要重新准备。要研究混频的连续变化，可改变上游可在线设置的实际输入，再从乘法器输出确认结果，不修改运行接线。</p><h2 id="下载与观察" tabindex="-1">下载与观察 <a class="header-anchor" href="#下载与观察" aria-label="Permalink to &quot;下载与观察&quot;">​</a></h2><h3 id="复数处理与-i-q-往返" tabindex="-1">复数处理与 I/Q 往返 <a class="header-anchor" href="#复数处理与-i-q-往返" aria-label="Permalink to &quot;复数处理与 I/Q 往返&quot;">​</a></h3><p><a href="../../../downloads/v0.1.0-alpha/complex-iq.cnsproj" download>下载 complex-iq.cnsproj</a></p><p>在 PC 上打开工程，按 F5 运行。有限运行可将参考源样本数设为 2048 item；重新打开工程后需再次运行以取得数据。</p><p>复数处理与 I/Q 往返</p><ul><li>观察复数旋转相量、乘 j 的相位变化及 I/Q 分解再合成；复数频谱保留正负频率。</li></ul><p>复数处理示例中的两个相量频率为 64 Hz 和 768 Hz。乘积预期形成 832 Hz 相量；与实数乘法的和频／差频同时出现进行比较，理解普通复数乘法的区别。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>为什么没看到差频？</strong> 普通复数乘法相加相位，只有相反符号的频率相乘才形成相应差值。</p><p><strong>只想改变固定相位？</strong> 使用复数增益器乘固定相量更直接。</p>',26)])])}const u=e(r,[["render",l]]);export{m as __pageData,u as default};
